#include "leds.h"

#include <NeoPixelBus.h>

#include "config.h"

static_assert(LED_PIN != 1, "GPIO1 is the serial TX pin; set the Dig-Uno LED1 jumper to GPIO16");

// I2S DMA output: the bitstream is generated by hardware, so Wi-Fi interrupts can't
// corrupt LED timing, and show() returns immediately.
#if LED_RGBW
using Strip = NeoPixelBus<NeoGrbwFeature, NeoEsp32I2s1Sk6812Method>;
#else
using Strip = NeoPixelBus<NeoGrbFeature, NeoEsp32I2s1Ws2812xMethod>;
#endif

namespace leds {
namespace {
Strip* strip = nullptr;
size_t n = 0;
}  // namespace

void begin(size_t count) {
  n = count;
  strip = new Strip(count, LED_PIN);
  strip->Begin();
  strip->ClearTo(0);
  strip->Show();
}

bool ready() { return strip->CanShow(); }

void show(const uint8_t* px) {
  for (size_t i = 0; i < n; ++i) {
#if LED_RGBW
    const uint8_t* p = px + i * 4;
    strip->SetPixelColor(i, RgbwColor(p[0], p[1], p[2], p[3]));
#else
    const uint8_t* p = px + i * 3;
    strip->SetPixelColor(i, RgbColor(p[0], p[1], p[2]));
#endif
  }
  strip->Show();
}

}  // namespace leds
